package com.piet.vms.service;

import com.piet.vms.config.Database;
import com.piet.vms.model.User;

import java.sql.*;
import java.time.LocalDate;
import java.time.LocalTime;
import java.util.ArrayList;
import java.util.List;

/** Application use-cases. All user-supplied values are sent through PreparedStatement. */
public final class AppService {
    public record HodOption(long id, String name, String department) { @Override public String toString(){ return name + (department==null?"":" — "+department); } }
    public record EventForm(String title,String description,LocalDate date,LocalTime time,String venue,int volunteers,LocalDate deadline,String reward,long hodId) {}

    public List<HodOption> getHods() { List<HodOption> out=new ArrayList<>(); String sql="SELECT u.user_id,u.full_name,d.department_name FROM users u LEFT JOIN departments d ON d.department_id=u.department_id WHERE u.role='HOD' AND u.active=TRUE ORDER BY u.full_name";
        try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(sql);ResultSet r=p.executeQuery()){while(r.next())out.add(new HodOption(r.getLong(1),r.getString(2),r.getString(3)));return out;}catch(SQLException e){throw fail("Could not load HODs",e);} }

    public List<Object[]> dashboardStats(User u) { List<Object[]> rows=new ArrayList<>(); try(Connection c=Database.getConnection()) {
        if(u.role().name().equals("STUDENT")) { rows.add(new Object[]{count(c,"SELECT COUNT(*) FROM events WHERE status='APPROVED' AND event_date>=CURDATE()"),"Upcoming approved events"}); rows.add(new Object[]{count(c,"SELECT COUNT(*) FROM registrations WHERE student_id=?",u.id()),"My registrations"}); rows.add(new Object[]{count(c,"SELECT COUNT(*) FROM attendance WHERE student_id=? AND status='PRESENT'",u.id())*2,"Volunteer hours (2/event)"}); }
        else if(u.role().name().equals("HOST")){rows.add(new Object[]{count(c,"SELECT COUNT(*) FROM events WHERE host_id=?",u.id()),"Events created"});rows.add(new Object[]{count(c,"SELECT COUNT(*) FROM events WHERE host_id=? AND status='PENDING'",u.id()),"Awaiting HOD"});rows.add(new Object[]{count(c,"SELECT COUNT(*) FROM registrations r JOIN events e ON e.event_id=r.event_id WHERE e.host_id=? AND r.status='PENDING'",u.id()),"Applications to review"});}
        else if(u.role().name().equals("HOD")){rows.add(new Object[]{count(c,"SELECT COUNT(*) FROM events WHERE hod_id=? AND status='PENDING'",u.id()),"Pending approvals"});rows.add(new Object[]{count(c,"SELECT COUNT(*) FROM events WHERE hod_id=? AND status='APPROVED'",u.id()),"Approved events"});rows.add(new Object[]{count(c,"SELECT COUNT(*) FROM events WHERE hod_id=?",u.id()),"Total proposals"});}
        else {rows.add(new Object[]{count(c,"SELECT COUNT(*) FROM attendance"),"Attendance records"});rows.add(new Object[]{count(c,"SELECT COUNT(*) FROM attendance WHERE status='PRESENT'"),"Present"});rows.add(new Object[]{count(c,"SELECT COUNT(*) FROM events WHERE status='APPROVED'"),"Approved events"});}
        return rows;
    }catch(SQLException e){throw fail("Could not load dashboard",e);} }
    private int count(Connection c,String sql,Object... args)throws SQLException{try(PreparedStatement p=c.prepareStatement(sql)){for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);try(ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}}

    public List<Object[]> browseEvents() { return query("SELECT e.event_id,e.title,e.event_date,e.event_time,e.venue,e.volunteers_required,e.reward,e.status, e.registration_deadline, u.full_name, (SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.event_id AND r.status IN ('PENDING','ACCEPTED')) AS applied FROM events e JOIN users u ON u.user_id=e.host_id WHERE e.status='APPROVED' AND e.event_date>=CURDATE() ORDER BY e.event_date,e.event_time"); }
    public List<Object[]> myRegistrations(User u) { return query("SELECT e.title,e.event_date,e.event_time,r.status,r.applied_at,e.venue,e.reward FROM registrations r JOIN events e ON e.event_id=r.event_id WHERE r.student_id=? ORDER BY r.applied_at DESC",u.id()); }
    public List<Object[]> passport(User u) { return query("SELECT e.title,e.event_date,e.venue,a.status,CASE WHEN a.status='PRESENT' THEN 2 ELSE 0 END AS hours FROM attendance a JOIN events e ON e.event_id=a.event_id WHERE a.student_id=? ORDER BY e.event_date DESC",u.id()); }
    public Object[] eventDetails(User host,long eventId) { List<Object[]> rows=query("SELECT title,description,event_date,event_time,venue,volunteers_required,registration_deadline,reward,hod_id FROM events WHERE event_id=? AND host_id=?",eventId,host.id()); if(rows.isEmpty())throw new ServiceException("Event not found.");return rows.get(0); }
    public List<Object[]> hostEvents(User u) { return query("SELECT e.event_id,e.title,e.event_date,e.event_time,e.venue,e.volunteers_required,e.status,e.hod_feedback,e.registration_deadline,e.reward FROM events e WHERE e.host_id=? ORDER BY e.created_at DESC",u.id()); }
    public List<Object[]> hodPending(User u) { return query("SELECT e.event_id,e.title,e.event_date,e.event_time,h.full_name AS host,e.venue,e.volunteers_required,e.registration_deadline,e.reward,e.status FROM events e JOIN users h ON h.user_id=e.host_id WHERE e.hod_id=? AND e.status IN ('PENDING','CHANGES_REQUESTED') ORDER BY e.created_at",u.id()); }
    public List<Object[]> hodAll(User u) { return query("SELECT e.event_id,e.title,e.event_date,e.event_time,h.full_name AS host,e.venue,e.volunteers_required,e.status,e.hod_feedback FROM events e JOIN users h ON h.user_id=e.host_id WHERE e.hod_id=? ORDER BY e.created_at DESC",u.id()); }
    public List<Object[]> hostApplications(User u, Long eventId) { String sql="SELECT r.registration_id,e.title,s.full_name,s.registration_number,s.email,r.status,r.applied_at FROM registrations r JOIN events e ON e.event_id=r.event_id JOIN users s ON s.user_id=r.student_id WHERE e.host_id=?"+(eventId==null?"":" AND e.event_id=?")+" ORDER BY r.applied_at"; return eventId==null?query(sql,u.id()):query(sql,u.id(),eventId); }
    public List<Object[]> attendanceEvents(User u) { return query("SELECT DISTINCT e.event_id,e.title,e.event_date FROM events e JOIN registrations r ON r.event_id=e.event_id AND r.status='ACCEPTED' WHERE e.host_id=? ORDER BY e.event_date DESC",u.id()); }
    public List<Object[]> hostAttendance(User u, long eventId) { return query("SELECT r.registration_id,s.user_id,s.full_name,s.registration_number,COALESCE(a.status,'NOT MARKED') AS attendance FROM registrations r JOIN users s ON s.user_id=r.student_id JOIN events e ON e.event_id=r.event_id LEFT JOIN attendance a ON a.event_id=e.event_id AND a.student_id=s.user_id WHERE e.host_id=? AND e.event_id=? AND r.status='ACCEPTED' ORDER BY s.full_name",u.id(),eventId); }
    public List<Object[]> proctorAttendance() { return query("SELECT e.title,e.event_date,s.full_name,s.registration_number,a.status,h.full_name AS marked_by,a.marked_at FROM attendance a JOIN events e ON e.event_id=a.event_id JOIN users s ON s.user_id=a.student_id JOIN users h ON h.user_id=a.marked_by ORDER BY a.marked_at DESC"); }

    private List<Object[]> query(String sql,Object...args) { List<Object[]> out=new ArrayList<>(); try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(sql)){for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);try(ResultSet r=p.executeQuery()){ResultSetMetaData m=r.getMetaData();int n=m.getColumnCount();while(r.next()){Object[] row=new Object[n];for(int i=0;i<n;i++)row[i]=r.getObject(i+1);out.add(row);}}return out;}catch(SQLException e){throw fail("Database query failed",e);} }

    public void createEvent(User host,EventForm f){validate(f);String sql="INSERT INTO events(title,description,event_date,event_time,venue,volunteers_required,registration_deadline,reward,host_id,hod_id,status) VALUES(?,?,?,?,?,?,?,?,?,?,'PENDING')";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(sql)){bindEvent(p,f,host.id());p.executeUpdate();audit(c,host.id(),"EVENT_CREATED","EVENT",null,"Created event: "+f.title());}catch(SQLException e){throw fail("Could not create event",e);}}
    public void updateEvent(User host,long eventId,EventForm f){validate(f);try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{String check="SELECT status FROM events WHERE event_id=? AND host_id=? FOR UPDATE";String status;try(PreparedStatement p=c.prepareStatement(check)){p.setLong(1,eventId);p.setLong(2,host.id());try(ResultSet r=p.executeQuery()){if(!r.next())throw new ServiceException("Event not found or you do not own it.");status=r.getString(1);if(status.equals("CANCELLED"))throw new ServiceException("Cancelled events cannot be edited.");}}
        String sql="UPDATE events SET title=?,description=?,event_date=?,event_time=?,venue=?,volunteers_required=?,registration_deadline=?,reward=?,hod_id=?,status=?,hod_feedback=NULL WHERE event_id=? AND host_id=?";
        try(PreparedStatement p=c.prepareStatement(sql)){p.setString(1,f.title().trim());p.setString(2,blankNull(f.description()));p.setDate(3,Date.valueOf(f.date()));p.setTime(4,Time.valueOf(f.time()));p.setString(5,f.venue().trim());p.setInt(6,f.volunteers());p.setDate(7,Date.valueOf(f.deadline()));p.setString(8,blankNull(f.reward()));p.setLong(9,f.hodId());p.setString(10,"PENDING");p.setLong(11,eventId);p.setLong(12,host.id());p.executeUpdate();}
        audit(c,host.id(),"EVENT_UPDATED_REQUIRES_APPROVAL","EVENT",eventId,"Changed event details; approval reset to pending");c.commit();}catch(Exception ex){c.rollback();if(ex instanceof RuntimeException re)throw re;throw new ServiceException("Could not update event",ex);} }catch(SQLException e){throw fail("Could not update event",e);}}
    private void bindEvent(PreparedStatement p,EventForm f,long hostId)throws SQLException{p.setString(1,f.title().trim());p.setString(2,blankNull(f.description()));p.setDate(3,Date.valueOf(f.date()));p.setTime(4,Time.valueOf(f.time()));p.setString(5,f.venue().trim());p.setInt(6,f.volunteers());p.setDate(7,Date.valueOf(f.deadline()));p.setString(8,blankNull(f.reward()));p.setLong(9,hostId);p.setLong(10,f.hodId());}
    private void validate(EventForm f){if(f.title()==null||f.title().isBlank()||f.venue()==null||f.venue().isBlank()||f.date()==null||f.time()==null||f.deadline()==null||f.hodId()<=0)throw new ServiceException("Complete all required event fields.");if(f.volunteers()<1)throw new ServiceException("Volunteers required must be at least 1.");if(f.deadline().isAfter(f.date()))throw new ServiceException("Registration deadline cannot be after the event date.");if(f.date().isBefore(LocalDate.now()))throw new ServiceException("Event date cannot be in the past.");}
    public void register(User student,long eventId){try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{String sql="SELECT volunteers_required,registration_deadline,event_date,status,(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.event_id AND r.status IN ('PENDING','ACCEPTED')) AS applied FROM events e WHERE event_id=? FOR UPDATE";int cap;Date deadline,date;String status;int applied;try(PreparedStatement p=c.prepareStatement(sql)){p.setLong(1,eventId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new ServiceException("Event not found.");cap=r.getInt(1);deadline=r.getDate(2);date=r.getDate(3);status=r.getString(4);applied=r.getInt(5);}}if(!status.equals("APPROVED"))throw new ServiceException("This event is not open for registration.");if(deadline.toLocalDate().isBefore(LocalDate.now()))throw new ServiceException("Registration deadline has passed.");if(date.toLocalDate().isBefore(LocalDate.now()))throw new ServiceException("This event has already passed.");if(applied>=cap)throw new ServiceException("Registration is closed: the required number of applications has been reached.");try(PreparedStatement p=c.prepareStatement("INSERT INTO registrations(event_id,student_id,status) VALUES(?,?,'PENDING')")){p.setLong(1,eventId);p.setLong(2,student.id());p.executeUpdate();}audit(c,student.id(),"STUDENT_REGISTERED","EVENT",eventId,"Applied to event");c.commit();}catch(Exception ex){c.rollback();if(ex instanceof SQLException se&&se.getErrorCode()==1062)throw new ServiceException("You have already registered for this event.");if(ex instanceof RuntimeException re)throw re;throw new ServiceException("Could not register",ex);}}catch(SQLException e){throw fail("Could not register",e);}}
    public void decideEvent(User hod,long eventId,String decision,String feedback){if(!List.of("APPROVED","REJECTED","CHANGES_REQUESTED").contains(decision))throw new ServiceException("Invalid decision.");try(Connection c=Database.getConnection()){c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("UPDATE events SET status=?,hod_feedback=? WHERE event_id=? AND hod_id=? AND status IN ('PENDING','CHANGES_REQUESTED')")){p.setString(1,decision);p.setString(2,blankNull(feedback));p.setLong(3,eventId);p.setLong(4,hod.id());if(p.executeUpdate()!=1)throw new ServiceException("This proposal is no longer pending or is not assigned to you.");audit(c,hod.id(),"EVENT_"+decision,"EVENT",eventId,feedback);c.commit();}catch(Exception ex){c.rollback();if(ex instanceof RuntimeException re)throw re;throw new ServiceException("Could not save approval decision",ex);}}catch(SQLException e){throw fail("Could not save approval decision",e);}}
    public void decideApplication(User host,long registrationId,String decision){if(!List.of("ACCEPTED","REJECTED").contains(decision))throw new ServiceException("Invalid application decision.");try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{long eventId;int cap;try(PreparedStatement p=c.prepareStatement("SELECT e.event_id,e.volunteers_required FROM registrations r JOIN events e ON e.event_id=r.event_id WHERE r.registration_id=? AND e.host_id=? AND e.status='APPROVED' FOR UPDATE")){p.setLong(1,registrationId);p.setLong(2,host.id());try(ResultSet r=p.executeQuery()){if(!r.next())throw new ServiceException("Application not found, or event is not approved.");eventId=r.getLong(1);cap=r.getInt(2);}}if(decision.equals("ACCEPTED")){try(PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM registrations WHERE event_id=? AND status='ACCEPTED' AND registration_id<>?")){p.setLong(1,eventId);p.setLong(2,registrationId);try(ResultSet r=p.executeQuery()){r.next();if(r.getInt(1)>=cap)throw new ServiceException("The event already has the required number of accepted volunteers.");}}}try(PreparedStatement p=c.prepareStatement("UPDATE registrations SET status=?,reviewed_at=CURRENT_TIMESTAMP WHERE registration_id=? AND status='PENDING'")){p.setString(1,decision);p.setLong(2,registrationId);if(p.executeUpdate()!=1)throw new ServiceException("This application has already been reviewed.");}audit(c,host.id(),"APPLICATION_"+decision,"REGISTRATION",registrationId,null);c.commit();}catch(Exception ex){c.rollback();if(ex instanceof RuntimeException re)throw re;throw new ServiceException("Could not review application",ex);}}catch(SQLException e){throw fail("Could not review application",e);}}
    public void cancelEvent(User host,long eventId){try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE events SET status='CANCELLED' WHERE event_id=? AND host_id=? AND status='APPROVED'")){p.setLong(1,eventId);p.setLong(2,host.id());if(p.executeUpdate()!=1)throw new ServiceException("Only your approved events can be cancelled.");audit(host.id(),"EVENT_CANCELLED","EVENT",eventId,"Host cancelled approved event");}catch(SQLException e){throw fail("Could not cancel event",e);}}
    public void markAttendance(User host,long eventId,long studentId,String status){if(!List.of("PRESENT","ABSENT").contains(status))throw new ServiceException("Invalid attendance status.");try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{try(PreparedStatement check=c.prepareStatement("SELECT COUNT(*) FROM events e JOIN registrations r ON r.event_id=e.event_id WHERE e.event_id=? AND e.host_id=? AND r.student_id=? AND r.status='ACCEPTED'")){check.setLong(1,eventId);check.setLong(2,host.id());check.setLong(3,studentId);try(ResultSet r=check.executeQuery()){r.next();if(r.getInt(1)!=1)throw new ServiceException("Only accepted volunteers for your event can have attendance recorded.");}}try(PreparedStatement p=c.prepareStatement("INSERT INTO attendance(event_id,student_id,status,marked_by) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),marked_by=VALUES(marked_by),marked_at=CURRENT_TIMESTAMP")){p.setLong(1,eventId);p.setLong(2,studentId);p.setString(3,status);p.setLong(4,host.id());p.executeUpdate();}audit(c,host.id(),"ATTENDANCE_"+status,"EVENT",eventId,"Student ID "+studentId);c.commit();}catch(Exception ex){c.rollback();if(ex instanceof RuntimeException re)throw re;throw new ServiceException("Could not record attendance",ex);}}catch(SQLException e){throw fail("Could not record attendance",e);}}
    private void audit(long actor,String action,String type,Long id,String details)throws SQLException{try(Connection c=Database.getConnection()){audit(c,actor,action,type,id,details);}}
    private void audit(Connection c,long actor,String action,String type,Long id,String details)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)")){p.setLong(1,actor);p.setString(2,action);p.setString(3,type);if(id==null)p.setNull(4,Types.BIGINT);else p.setLong(4,id);p.setString(5,details);p.executeUpdate();}}
    private String blankNull(String s){return s==null||s.isBlank()?null:s.trim();}
    private ServiceException fail(String message,SQLException e){return new ServiceException(message+": "+e.getMessage(),e);}
}
